import logging
import re
import time
from ta_attenuator.utils.telnet import TelnetClient
from ta_attenuator.attenuator import Attenuator
from ta_attenuator.attenuator import ChangingAttenutionValueOfNotReservedPort
from ta_attenuator.attenuator import ReadingAttenuationValueOfNonexistentRFPath
from ta_attenuator.attenuator import AttenuationValueIsOtherThanExpected


class RadioRackAttenuator(Attenuator):
    """Implementation of RadioRack attenuator"""

    # pylint: disable=anomalous-backslash-in-string, bare-except

    def __init__(self, min_attenuation, max_attenuation, ip, port=50000):
        super(RadioRackAttenuator, self).__init__()
        self.ip = ip
        self.port = port
        self.conn = None
        self.telnet = TelnetClient()
        self.is_connected = False
        self.min_attenuation = min_attenuation
        self.max_attenuation = max_attenuation

    def connect_attenuator_controller(self, **kwargs):
        """
        Establish connection with attenuation controller
        allowing to change attenuation on specific RF-path of that device
        """
        if not self.is_connected:
            self.telnet.connect(self.ip, self.port)
            self.is_connected = True
            logging.info('Connection to RadioRack attenuator established.')

    def disconnect_attenuator_controller(self, **kwargs):
        """
        Release connection with attenuation controller
        """
        if not self.used_ports:
            self.telnet.close_connection()
        else:
            logging.info("Did not disconnect controller, because ports {} are still used.".format(self.used_ports))

    def read_rf_paths_attenuation(self, rf_paths):
        """read attenuation value in db for the first rf_path"""
        return self._read_value_of_rf_path(str(rf_paths[0]))

    def _set_single_rf_path_decibel_attenuation(self, rf_path_address, attenuation_value_db, confirm=True):
        if not self.check_if_port_is_reserved(rf_path_address):
            raise ChangingAttenutionValueOfNotReservedPort("Port {} was not reserved on attenuator!"
                                                           "Please check if this RF path "
                                                           "belongs to your cell.".format(rf_path_address))
        attenuation_value_db = int(round(attenuation_value_db, 1))
        cmd = "ATT {} {}".format(rf_path_address, attenuation_value_db)
        self._write(cmd)
        try:
            self._make_sure_port_has_correct_value(rf_path_address, attenuation_value_db, confirm)
        except:
            self._write(cmd)
            self._make_sure_port_has_correct_value(rf_path_address, attenuation_value_db, confirm)
        logging.info('Port ID {} value successfuly set to {} dB.'.format(rf_path_address, attenuation_value_db))

    def _write(self, cmd):
        time.sleep(0.5)
        logging.debug('Sending command to RadioRack attenuator: {}'.format(cmd))
        resp = self.telnet.read_command(cmd, read_method='until')
        logging.debug('The response of Sending command: {}'.format(resp))

    def get_max_decibel_attenuation(self):
        """
        Returns Maximal value of attenuation possible on this attenuator. For ex. 95 dB
        :return: float
        """
        return self.max_attenuation

    def get_min_decibel_attenuation(self):
        """
        Returns Minimal value of attenuation possible on this attenuator. For ex. 5 dB
        :return: float
        """
        return self.min_attenuation

    def _read_value_of_rf_path(self, rf_path_address):
        time.sleep(0.5)
        att_output = self.telnet.read_command('ATT', read_method='until')
        logging.debug('Attenuator state: {}'.format(att_output))
        REGEX = 'ATT\s{1,}' + str(rf_path_address) + '\s{1,}(\d{1,})'
        re_out = re.search(REGEX, att_output)
        if re_out:
            logging.debug(re_out.groups()[0])
            value_read = re_out.groups()[0]
            logging.debug('Port ID {} state = {}'.format(str(rf_path_address), value_read))
            return value_read
        else:
            raise ReadingAttenuationValueOfNonexistentRFPath("Failed to read attenuation of rf path {}."
                                                             "Make sure that path exists. If it exists,"
                                                             "then connections limit may be exceeded - "
                                                             "try to release existing connections to "
                                                             "attenuator.".format(rf_path_address))

    def _make_sure_port_has_correct_value(self, port_id, value_desired, confirm):
        if confirm:
            value_read = self._read_value_of_rf_path(str(port_id))
            if int(value_read) != int(value_desired):
                raise AttenuationValueIsOtherThanExpected('Desired port id {} value {} not set on attenuator! '
                                                          'Output from RA {} = {}'.format(port_id,
                                                                                          value_desired, port_id,
                                                                                          value_read))
